import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"40、【解】 坎下震上","description":"温公易说 - 40、【解】 坎下震上","frontmatter":{"title":"40、【解】 坎下震上","description":"温公易说 - 40、【解】 坎下震上"},"headers":[],"relativePath":"zh/classics/wengong/041.md","filePath":"zh/classics/wengong/041.md"}'),n={name:"zh/classics/wengong/041.md"};function l(t,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_40、【解】-坎下震上" tabindex="-1">40、【解】 坎下震上 <a class="header-anchor" href="#_40、【解】-坎下震上" aria-label="Permalink to “40、【解】 坎下震上”">​</a></h1><h3 id="彖曰-解-险以动-动而免乎险-解。解-利西南-往得众也。其来复吉-乃得中也。有攸往-夙吉-往有功也。天地解而雷雨作-雷雨作而百果草木皆甲坼。解之时-大矣哉。" tabindex="-1">彖曰：解，险以动，动而免乎险，解。解，利西南，往得众也。其来复吉，乃得中也。有攸往，夙吉，往有功也。天地解而雷雨作，雷雨作而百果草木皆甲坼。解之时，大矣哉。 <a class="header-anchor" href="#彖曰-解-险以动-动而免乎险-解。解-利西南-往得众也。其来复吉-乃得中也。有攸往-夙吉-往有功也。天地解而雷雨作-雷雨作而百果草木皆甲坼。解之时-大矣哉。" aria-label="Permalink to “彖曰：解，险以动，动而免乎险，解。解，利西南，往得众也。其来复吉，乃得中也。有攸往，夙吉，往有功也。天地解而雷雨作，雷雨作而百果草木皆甲坼。解之时，大矣哉。”">​</a></h3><p>解无所往，其来复吉，有攸往，夙吉何也？夫能济难者，存乎中。能有功者，存乎时。时未可往而用之太速，则不达。时可以往而应之太缓，则无功。故上六藏器于身，待时而动，君子韪之。</p><h3 id="象曰-雷雨作-解。君子以赦过宥罪。" tabindex="-1">象曰：雷雨作，解。君子以赦过宥罪。 <a class="header-anchor" href="#象曰-雷雨作-解。君子以赦过宥罪。" aria-label="Permalink to “象曰：雷雨作，解。君子以赦过宥罪。”">​</a></h3><h3 id="初六-无咎-象曰-刚柔之际-义无咎也。" tabindex="-1">初六：无咎 象曰：刚柔之际，义无咎也。 <a class="header-anchor" href="#初六-无咎-象曰-刚柔之际-义无咎也。" aria-label="Permalink to “初六：无咎 象曰：刚柔之际，义无咎也。”">​</a></h3><h3 id="九二-田获三狐-得黄矢-贞吉-象曰-九二贞吉-得中道也。" tabindex="-1">九二：田获三狐，得黄矢，贞吉 象曰：九二贞吉，得中道也。 <a class="header-anchor" href="#九二-田获三狐-得黄矢-贞吉-象曰-九二贞吉-得中道也。" aria-label="Permalink to “九二：田获三狐，得黄矢，贞吉 象曰：九二贞吉，得中道也。”">​</a></h3><h3 id="六三-负且乘-致寇至-贞吝-象曰-负且乘-亦可丑也。自我致戎-又谁咎也。" tabindex="-1">六三：负且乘，致寇至，贞吝 象曰：负且乘，亦可丑也。自我致戎，又谁咎也。 <a class="header-anchor" href="#六三-负且乘-致寇至-贞吝-象曰-负且乘-亦可丑也。自我致戎-又谁咎也。" aria-label="Permalink to “六三：负且乘，致寇至，贞吝 象曰：负且乘，亦可丑也。自我致戎，又谁咎也。”">​</a></h3><h3 id="九四-解而拇-朋至斯孚-象曰-解而拇-未当位也。" tabindex="-1">九四：解而拇，朋至斯孚 象曰：解而拇，未当位也。 <a class="header-anchor" href="#九四-解而拇-朋至斯孚-象曰-解而拇-未当位也。" aria-label="Permalink to “九四：解而拇，朋至斯孚 象曰：解而拇，未当位也。”">​</a></h3><h3 id="六五-君子维有解-吉。有孚于小人-象曰-君子有解-小人退也。" tabindex="-1">六五：君子维有解，吉。有孚于小人 象曰：君子有解，小人退也。 <a class="header-anchor" href="#六五-君子维有解-吉。有孚于小人-象曰-君子有解-小人退也。" aria-label="Permalink to “六五：君子维有解，吉。有孚于小人 象曰：君子有解，小人退也。”">​</a></h3><h3 id="上六-公用射隼于高墉之上-获之-无不利-象曰-公用射隼-以解悖也。" tabindex="-1">上六：公用射隼于高墉之上，获之，无不利 象曰：公用射隼，以解悖也。 <a class="header-anchor" href="#上六-公用射隼于高墉之上-获之-无不利-象曰-公用射隼-以解悖也。" aria-label="Permalink to “上六：公用射隼于高墉之上，获之，无不利 象曰：公用射隼，以解悖也。”">​</a></h3>',10)])])}const f=e(n,[["render",l]]);export{b as __pageData,f as default};
